/** Bài chờ QC xác nhận của một lớp */
export const choDuyetCuaLop = (classId: number) =>
  BAI_NOP.filter((b) => b.classId === classId && b.tuLuan);

/** Bài máy đã chấm của một lớp — chỉ xem, không duyệt */
export const mayChamCuaLop = (classId: number) =>
  BAI_NOP.filter((b) => b.classId === classId && !b.tuLuan);
